-- CloudPilot target schema (27 tables) - DRAFT PostgreSQL 16 DDL
-- Generated from project_context. NOT a migration: implement with Alembic, one revision per domain (see 04 section 8).
-- Tables 1-9 exist in the code (columns of plans/subscriptions are inferred - verify against the models).
-- Marker: -- [P] = proposed addition/change that is not in the original ERD.
-- Conventions: UUID PK generated by the app, TIMESTAMPTZ, VARCHAR+CHECK instead of enums, ON DELETE RESTRICT everywhere.

BEGIN;

-- 1. users [Identity] ✅  A person who signed in with GitHub.
CREATE TABLE users (
    id uuid NOT NULL,
    github_user_id varchar(64) NOT NULL,
    name varchar(255),
    email varchar(320),
    avatar_url text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uq_users_github_user_id UNIQUE (github_user_id),
    CONSTRAINT uq_users_email UNIQUE (email)
);

-- 2. teams [Identity] ✅  Tenant / workspace. Owns projects, AWS accounts, subscription.
CREATE TABLE teams (
    id uuid NOT NULL,
    name varchar(255) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_teams PRIMARY KEY (id)
);

-- 3. team_members [Identity] ✅  Junction users↔teams with a role.
CREATE TABLE team_members (
    team_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role varchar(16) NOT NULL,
    joined_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_team_members PRIMARY KEY (team_id, user_id),
    CONSTRAINT fk_team_members_team_id_teams FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE RESTRICT,
    CONSTRAINT fk_team_members_user_id_users FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT ck_team_members_role CHECK (role IN ('OWNER', 'ADMIN', 'MEMBER'))
);
CREATE INDEX ix_team_members_user_id ON team_members (user_id);

-- 4. plans [Subscription] ✅  Catalog of plans (FREE, STANDARD). Missing from the ERD (D1). Column list is inferred from the README/seed, verify against the model.
CREATE TABLE plans (
    id uuid NOT NULL,
    code varchar(32) NOT NULL,
    name varchar(100) NOT NULL,
    price_monthly numeric(10,2) NOT NULL DEFAULT 0,
    limits jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_plans PRIMARY KEY (id),
    CONSTRAINT uq_plans_code UNIQUE (code)
);

-- 5. subscriptions [Subscription] ✅  A team's plan. Missing from the ERD (D1). Inferred columns, verify against the model.
CREATE TABLE subscriptions (
    id uuid NOT NULL,
    team_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    status varchar(16) NOT NULL,
    started_at timestamptz NOT NULL DEFAULT now(),
    ended_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_subscriptions PRIMARY KEY (id),
    CONSTRAINT fk_subscriptions_team_id_teams FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscriptions_plan_id_plans FOREIGN KEY (plan_id) REFERENCES plans (id) ON DELETE RESTRICT,
    CONSTRAINT ck_subscriptions_status CHECK (status IN ('ACTIVE', 'TRIALING', 'PAST_DUE', 'CANCELED'))
);
CREATE INDEX ix_subscriptions_team_id ON subscriptions (team_id);
CREATE INDEX ix_subscriptions_plan_id ON subscriptions (plan_id);
CREATE UNIQUE INDEX uq_subscriptions_one_active_per_team ON subscriptions (team_id) WHERE status IN ('ACTIVE','TRIALING');

-- 6. projects [Project] ✅  A deployable application. Archived, never deleted.
CREATE TABLE projects (
    id uuid NOT NULL,
    team_id uuid NOT NULL,
    name varchar(255) NOT NULL,
    description text,
    status varchar(16) NOT NULL DEFAULT 'ACTIVE',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_projects PRIMARY KEY (id),
    CONSTRAINT fk_projects_team_id_teams FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE RESTRICT,
    CONSTRAINT ck_projects_status CHECK (status IN ('ACTIVE', 'ARCHIVED'))
);
CREATE INDEX ix_projects_team_id ON projects (team_id);

-- 7. repositories [Source Control] ✅  GitHub repo connected to a project. Metadata only, never source code.
CREATE TABLE repositories (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    github_repository_id varchar(64) NOT NULL,
    owner varchar(255) NOT NULL,
    name varchar(255) NOT NULL,
    url text NOT NULL,
    default_branch varchar(255) NOT NULL,
    connected_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_repositories PRIMARY KEY (id),
    CONSTRAINT fk_repositories_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT
);
CREATE INDEX ix_repositories_project_id ON repositories (project_id);
ALTER TABLE repositories ADD CONSTRAINT uq_repositories_project_id_github_repository_id UNIQUE (project_id, github_repository_id);

-- 8. branches [Source Control] ✅  Branches of a repo. Exactly one deployment branch per repo.
CREATE TABLE branches (
    id uuid NOT NULL,
    repository_id uuid NOT NULL,
    name varchar(255) NOT NULL,
    is_default boolean NOT NULL DEFAULT false,
    is_deployment_branch boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_branches PRIMARY KEY (id),
    CONSTRAINT fk_branches_repository_id_repositories FOREIGN KEY (repository_id) REFERENCES repositories (id) ON DELETE RESTRICT
);
CREATE INDEX ix_branches_repository_id ON branches (repository_id);
ALTER TABLE branches ADD CONSTRAINT uq_branches_repository_id_name UNIQUE (repository_id, name);
CREATE UNIQUE INDEX uq_branches_one_deployment_branch ON branches (repository_id) WHERE is_deployment_branch;

-- 9. commits [Source Control] ✅  Immutable commit records of the deployment branch.
CREATE TABLE commits (
    id uuid NOT NULL,
    repository_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    sha varchar(40) NOT NULL,
    message text,
    author_name varchar(255),
    author_email varchar(320),
    committed_at timestamptz NOT NULL,
    detected_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_commits PRIMARY KEY (id),
    CONSTRAINT fk_commits_repository_id_repositories FOREIGN KEY (repository_id) REFERENCES repositories (id) ON DELETE RESTRICT,
    CONSTRAINT fk_commits_branch_id_branches FOREIGN KEY (branch_id) REFERENCES branches (id) ON DELETE RESTRICT
);
CREATE INDEX ix_commits_repository_id ON commits (repository_id);
CREATE INDEX ix_commits_branch_id ON commits (branch_id);
ALTER TABLE commits ADD CONSTRAINT uq_commits_repository_id_sha UNIQUE (repository_id, sha);
CREATE INDEX ix_commits_repository_id_committed_at ON commits (repository_id, committed_at DESC);

-- 10. repository_analyses [Analysis] 📋  One run of the Analysis Agent on a repo at a commit = the 'analysis job'.
CREATE TABLE repository_analyses (
    id uuid NOT NULL,
    repository_id uuid NOT NULL,
    commit_id uuid NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'QUEUED',
    created_at timestamptz NOT NULL DEFAULT now(),  -- [P]
    started_at timestamptz,
    completed_at timestamptz,
    requested_by uuid,  -- [P]
    report_schema_version varchar(8),  -- [P]
    error_code varchar(64),
    error_message text,
    analysis_data jsonb,  -- validated AnalysisReport; evidence metadata only, no source excerpts
    CONSTRAINT pk_repository_analyses PRIMARY KEY (id),
    CONSTRAINT fk_repository_analyses_repository_id_repositories FOREIGN KEY (repository_id) REFERENCES repositories (id) ON DELETE RESTRICT,
    CONSTRAINT fk_repository_analyses_commit_id_commits FOREIGN KEY (commit_id) REFERENCES commits (id) ON DELETE RESTRICT,
    CONSTRAINT ck_repository_analyses_status CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCESS', 'BLOCKED', 'FAILED', 'TIMED_OUT', 'CANCELLED')),
    CONSTRAINT fk_repository_analyses_requested_by_users FOREIGN KEY (requested_by) REFERENCES users (id) ON DELETE RESTRICT
);
CREATE INDEX ix_repository_analyses_repository_id ON repository_analyses (repository_id);
CREATE INDEX ix_repository_analyses_commit_id ON repository_analyses (commit_id);
CREATE INDEX ix_repository_analyses_requested_by ON repository_analyses (requested_by);
CREATE INDEX ix_repository_analyses_status_created_at ON repository_analyses (status, created_at);

-- 11. services [Analysis] 📋  Normalized DetectedService rows of one analysis.
CREATE TABLE services (
    id uuid NOT NULL,
    analysis_id uuid NOT NULL,
    name varchar(255) NOT NULL,
    service_type varchar(32) NOT NULL,
    language varchar(64),
    framework varchar(64),
    path varchar(1024) NOT NULL DEFAULT '.',
    port integer,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_services PRIMARY KEY (id),
    CONSTRAINT fk_services_analysis_id_repository_analyses FOREIGN KEY (analysis_id) REFERENCES repository_analyses (id) ON DELETE RESTRICT,
    CONSTRAINT ck_services_port CHECK (port IS NULL OR port BETWEEN 1 AND 65535)
);
CREATE INDEX ix_services_analysis_id ON services (analysis_id);

-- 12. architectures [Architecture] 📋  Named design container; versions hold the content.
CREATE TABLE architectures (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    name varchar(255) NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'ACTIVE',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_architectures PRIMARY KEY (id),
    CONSTRAINT fk_architectures_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT ck_architectures_status CHECK (status IN ('ACTIVE', 'ARCHIVED'))
);
CREATE INDEX ix_architectures_project_id ON architectures (project_id);

-- 13. architecture_versions [Architecture] 📋  Immutable numbered snapshot of the AWS design (ArchitecturePlan).
CREATE TABLE architecture_versions (
    id uuid NOT NULL,
    architecture_id uuid NOT NULL,
    version_number integer NOT NULL,
    source_analysis_id uuid,
    status varchar(16) NOT NULL DEFAULT 'DRAFT',
    architecture_data jsonb NOT NULL,
    created_by uuid,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_architecture_versions PRIMARY KEY (id),
    CONSTRAINT fk_architecture_versions_architecture_id_architectures FOREIGN KEY (architecture_id) REFERENCES architectures (id) ON DELETE RESTRICT,
    CONSTRAINT ck_architecture_versions_version_number CHECK (version_number > 0),
    CONSTRAINT fk_architecture_versions_source_analysis_id_repository_analyses FOREIGN KEY (source_analysis_id) REFERENCES repository_analyses (id) ON DELETE RESTRICT,
    CONSTRAINT ck_architecture_versions_status CHECK (status IN ('DRAFT', 'VALIDATED', 'INVALID', 'APPROVED', 'SUPERSEDED')),
    CONSTRAINT fk_architecture_versions_created_by_users FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE RESTRICT
);
CREATE INDEX ix_architecture_versions_architecture_id ON architecture_versions (architecture_id);
CREATE INDEX ix_architecture_versions_source_analysis_id ON architecture_versions (source_analysis_id);
CREATE INDEX ix_architecture_versions_created_by ON architecture_versions (created_by);
ALTER TABLE architecture_versions ADD CONSTRAINT uq_architecture_versions_architecture_id_version_number UNIQUE (architecture_id, version_number);

-- 14. cost_estimates [Cost] 📋  Estimated monthly cost of one architecture version.
CREATE TABLE cost_estimates (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    architecture_version_id uuid NOT NULL,
    estimated_monthly_cost numeric(12,2) NOT NULL,
    currency char(3) NOT NULL DEFAULT 'USD',
    breakdown jsonb NOT NULL,
    calculated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_cost_estimates PRIMARY KEY (id),
    CONSTRAINT fk_cost_estimates_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_cost_estimates_architecture_version_id_architecture_versions FOREIGN KEY (architecture_version_id) REFERENCES architecture_versions (id) ON DELETE RESTRICT
);
CREATE INDEX ix_cost_estimates_project_id ON cost_estimates (project_id);
CREATE INDEX ix_cost_estimates_architecture_version_id ON cost_estimates (architecture_version_id);

-- 15. aws_accounts [AWS] 📋  Customer AWS account reached through IAM role + External ID. Never stores keys.
CREATE TABLE aws_accounts (
    id uuid NOT NULL,
    team_id uuid NOT NULL,
    aws_account_id varchar(12) NOT NULL,
    role_arn text,
    readonly_role_arn text,  -- [P]
    external_id varchar(64) NOT NULL,  -- [P]
    default_region varchar(32) NOT NULL,
    status varchar(24) NOT NULL DEFAULT 'PENDING_VERIFICATION',
    connected_at timestamptz NOT NULL DEFAULT now(),
    last_verified_at timestamptz,
    CONSTRAINT pk_aws_accounts PRIMARY KEY (id),
    CONSTRAINT fk_aws_accounts_team_id_teams FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE RESTRICT,
    CONSTRAINT ck_aws_accounts_status CHECK (status IN ('PENDING_VERIFICATION', 'ACTIVE', 'VERIFICATION_FAILED', 'DISCONNECTED'))
);
CREATE INDEX ix_aws_accounts_team_id ON aws_accounts (team_id);
CREATE UNIQUE INDEX uq_aws_accounts_team_id_aws_account_id ON aws_accounts (team_id, aws_account_id) WHERE status <> 'DISCONNECTED';
ALTER TABLE aws_accounts ADD CONSTRAINT uq_aws_accounts_external_id UNIQUE (external_id);

-- 16. deployments [Deployment] 📋  One deployment attempt. Pins the exact commit + architecture version + AWS account.
CREATE TABLE deployments (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    repository_id uuid NOT NULL,
    commit_id uuid NOT NULL,
    architecture_version_id uuid NOT NULL,
    aws_account_id uuid NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'QUEUED',
    trigger_type varchar(16) NOT NULL DEFAULT 'MANUAL',
    created_at timestamptz NOT NULL DEFAULT now(),  -- [P]
    started_at timestamptz,
    completed_at timestamptz,
    error_code varchar(64),
    error_message text,
    created_by uuid,
    CONSTRAINT pk_deployments PRIMARY KEY (id),
    CONSTRAINT fk_deployments_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_deployments_repository_id_repositories FOREIGN KEY (repository_id) REFERENCES repositories (id) ON DELETE RESTRICT,
    CONSTRAINT fk_deployments_commit_id_commits FOREIGN KEY (commit_id) REFERENCES commits (id) ON DELETE RESTRICT,
    CONSTRAINT fk_deployments_architecture_version_id_architecture_versions FOREIGN KEY (architecture_version_id) REFERENCES architecture_versions (id) ON DELETE RESTRICT,
    CONSTRAINT fk_deployments_aws_account_id_aws_accounts FOREIGN KEY (aws_account_id) REFERENCES aws_accounts (id) ON DELETE RESTRICT,
    CONSTRAINT ck_deployments_status CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCESS', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_deployments_trigger_type CHECK (trigger_type IN ('MANUAL', 'AUTO', 'RETRY', 'HEALING')),
    CONSTRAINT fk_deployments_created_by_users FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE RESTRICT
);
CREATE INDEX ix_deployments_project_id ON deployments (project_id);
CREATE INDEX ix_deployments_repository_id ON deployments (repository_id);
CREATE INDEX ix_deployments_commit_id ON deployments (commit_id);
CREATE INDEX ix_deployments_architecture_version_id ON deployments (architecture_version_id);
CREATE INDEX ix_deployments_aws_account_id ON deployments (aws_account_id);
CREATE INDEX ix_deployments_created_by ON deployments (created_by);
CREATE UNIQUE INDEX uq_deployments_one_active_per_project ON deployments (project_id) WHERE status IN ('QUEUED','RUNNING');
CREATE INDEX ix_deployments_project_id_created_at ON deployments (project_id, created_at DESC);

-- 17. deployment_steps [Deployment] 📋  Ordered stage of a deployment, so the failing step is identifiable.
CREATE TABLE deployment_steps (
    id uuid NOT NULL,
    deployment_id uuid NOT NULL,
    step_type varchar(32) NOT NULL,
    step_order integer NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'QUEUED',
    created_at timestamptz NOT NULL DEFAULT now(),  -- [P]
    started_at timestamptz,
    completed_at timestamptz,
    error_code varchar(64),
    error_message text,
    input_data jsonb,
    output_data jsonb,
    CONSTRAINT pk_deployment_steps PRIMARY KEY (id),
    CONSTRAINT fk_deployment_steps_deployment_id_deployments FOREIGN KEY (deployment_id) REFERENCES deployments (id) ON DELETE RESTRICT,
    CONSTRAINT ck_deployment_steps_step_order CHECK (step_order > 0),
    CONSTRAINT ck_deployment_steps_status CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCESS', 'FAILED', 'SKIPPED'))
);
CREATE INDEX ix_deployment_steps_deployment_id ON deployment_steps (deployment_id);
ALTER TABLE deployment_steps ADD CONSTRAINT uq_deployment_steps_deployment_id_step_order UNIQUE (deployment_id, step_order);

-- 18. infrastructure_resources [Deployment] 📋  AWS resources created by a deployment.
CREATE TABLE infrastructure_resources (
    id uuid NOT NULL,
    deployment_id uuid NOT NULL,
    resource_type varchar(64) NOT NULL,
    resource_name varchar(255) NOT NULL,
    aws_resource_id varchar(255),
    aws_arn text,
    region varchar(32) NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'ACTIVE',
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_infrastructure_resources PRIMARY KEY (id),
    CONSTRAINT fk_infrastructure_resources_deployment_id_deployments FOREIGN KEY (deployment_id) REFERENCES deployments (id) ON DELETE RESTRICT,
    CONSTRAINT ck_infrastructure_resources_status CHECK (status IN ('CREATING', 'ACTIVE', 'FAILED', 'DESTROYED'))
);
CREATE INDEX ix_infrastructure_resources_deployment_id ON infrastructure_resources (deployment_id);

-- 19. monitoring_configs [Monitoring] 📋  Monitoring settings of a deployment.
CREATE TABLE monitoring_configs (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    deployment_id uuid NOT NULL,
    enabled boolean NOT NULL DEFAULT true,
    configuration jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_monitoring_configs PRIMARY KEY (id),
    CONSTRAINT fk_monitoring_configs_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_monitoring_configs_deployment_id_deployments FOREIGN KEY (deployment_id) REFERENCES deployments (id) ON DELETE RESTRICT
);
CREATE INDEX ix_monitoring_configs_project_id ON monitoring_configs (project_id);
CREATE INDEX ix_monitoring_configs_deployment_id ON monitoring_configs (deployment_id);
ALTER TABLE monitoring_configs ADD CONSTRAINT uq_monitoring_configs_deployment_id UNIQUE (deployment_id);

-- 20. alerts [Monitoring] 📋  A fired alert (metric crossed a threshold).
CREATE TABLE alerts (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    deployment_id uuid NOT NULL,
    severity varchar(16) NOT NULL,
    source varchar(32) NOT NULL,
    metric_name varchar(255) NOT NULL,
    threshold numeric,
    actual_value numeric,
    status varchar(16) NOT NULL DEFAULT 'FIRING',
    triggered_at timestamptz NOT NULL,
    resolved_at timestamptz,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT pk_alerts PRIMARY KEY (id),
    CONSTRAINT fk_alerts_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_alerts_deployment_id_deployments FOREIGN KEY (deployment_id) REFERENCES deployments (id) ON DELETE RESTRICT,
    CONSTRAINT ck_alerts_severity CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT ck_alerts_status CHECK (status IN ('FIRING', 'ACKNOWLEDGED', 'RESOLVED'))
);
CREATE INDEX ix_alerts_project_id ON alerts (project_id);
CREATE INDEX ix_alerts_deployment_id ON alerts (deployment_id);
CREATE INDEX ix_alerts_project_id_status ON alerts (project_id, status);

-- 21. cost_records [Cost] 📋  Actual cost of a period, imported from AWS, compared with estimates.
CREATE TABLE cost_records (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    aws_account_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    amount numeric(12,2) NOT NULL,
    currency char(3) NOT NULL DEFAULT 'USD',
    source varchar(32) NOT NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_cost_records PRIMARY KEY (id),
    CONSTRAINT fk_cost_records_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_cost_records_aws_account_id_aws_accounts FOREIGN KEY (aws_account_id) REFERENCES aws_accounts (id) ON DELETE RESTRICT,
    CONSTRAINT ck_cost_records_source CHECK (source IN ('COST_EXPLORER', 'MANUAL'))
);
CREATE INDEX ix_cost_records_project_id ON cost_records (project_id);
CREATE INDEX ix_cost_records_aws_account_id ON cost_records (aws_account_id);

-- 22. incidents [Incident] 📋  A detected problem on a project/deployment.
CREATE TABLE incidents (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    deployment_id uuid,
    alert_id uuid,
    title varchar(255) NOT NULL,
    description text,
    severity varchar(16) NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'OPEN',
    detected_at timestamptz NOT NULL,
    resolved_at timestamptz,
    root_cause text,
    diagnosis text,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT pk_incidents PRIMARY KEY (id),
    CONSTRAINT fk_incidents_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_incidents_deployment_id_deployments FOREIGN KEY (deployment_id) REFERENCES deployments (id) ON DELETE RESTRICT,
    CONSTRAINT fk_incidents_alert_id_alerts FOREIGN KEY (alert_id) REFERENCES alerts (id) ON DELETE RESTRICT,
    CONSTRAINT ck_incidents_severity CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT ck_incidents_status CHECK (status IN ('OPEN', 'INVESTIGATING', 'MITIGATING', 'RESOLVED', 'CLOSED'))
);
CREATE INDEX ix_incidents_project_id ON incidents (project_id);
CREATE INDEX ix_incidents_deployment_id ON incidents (deployment_id);
CREATE INDEX ix_incidents_alert_id ON incidents (alert_id);
CREATE INDEX ix_incidents_project_id_status ON incidents (project_id, status);

-- 23. agent_runs [AI Agents] 📋  One execution of an AI agent. Trace for analysis, architecture, diagnosis.
CREATE TABLE agent_runs (
    id uuid NOT NULL,
    project_id uuid NOT NULL,
    deployment_id uuid,
    incident_id uuid,
    agent_type varchar(24) NOT NULL,
    model varchar(64),
    status varchar(16) NOT NULL DEFAULT 'QUEUED',
    created_at timestamptz NOT NULL DEFAULT now(),  -- [P]
    started_at timestamptz,
    completed_at timestamptz,
    input_data jsonb,
    output_data jsonb,
    usage jsonb,  -- [P]
    error_code varchar(64),
    error_message text,
    CONSTRAINT pk_agent_runs PRIMARY KEY (id),
    CONSTRAINT fk_agent_runs_project_id_projects FOREIGN KEY (project_id) REFERENCES projects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_agent_runs_deployment_id_deployments FOREIGN KEY (deployment_id) REFERENCES deployments (id) ON DELETE RESTRICT,
    CONSTRAINT fk_agent_runs_incident_id_incidents FOREIGN KEY (incident_id) REFERENCES incidents (id) ON DELETE RESTRICT,
    CONSTRAINT ck_agent_runs_agent_type CHECK (agent_type IN ('ANALYSIS', 'ARCHITECTURE', 'DIAGNOSIS', 'HEALING')),
    CONSTRAINT ck_agent_runs_status CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCESS', 'BLOCKED', 'FAILED', 'TIMED_OUT', 'CANCELLED'))
);
CREATE INDEX ix_agent_runs_project_id ON agent_runs (project_id);
CREATE INDEX ix_agent_runs_deployment_id ON agent_runs (deployment_id);
CREATE INDEX ix_agent_runs_incident_id ON agent_runs (incident_id);

-- 24. agent_tasks [AI Agents] 📋  Ordered step inside an agent run (fetch, detect, validate ...).
CREATE TABLE agent_tasks (
    id uuid NOT NULL,
    agent_run_id uuid NOT NULL,
    task_type varchar(32) NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'QUEUED',
    step_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),  -- [P]
    input_data jsonb,
    output_data jsonb,
    started_at timestamptz,
    completed_at timestamptz,
    error_code varchar(64),
    error_message text,
    CONSTRAINT pk_agent_tasks PRIMARY KEY (id),
    CONSTRAINT fk_agent_tasks_agent_run_id_agent_runs FOREIGN KEY (agent_run_id) REFERENCES agent_runs (id) ON DELETE RESTRICT,
    CONSTRAINT ck_agent_tasks_status CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCESS', 'FAILED', 'SKIPPED')),
    CONSTRAINT ck_agent_tasks_step_order CHECK (step_order > 0)
);
CREATE INDEX ix_agent_tasks_agent_run_id ON agent_tasks (agent_run_id);
ALTER TABLE agent_tasks ADD CONSTRAINT uq_agent_tasks_agent_run_id_step_order UNIQUE (agent_run_id, step_order);

-- 25. healing_actions [Incident] 📋  Corrective action proposed for an incident.
CREATE TABLE healing_actions (
    id uuid NOT NULL,
    incident_id uuid NOT NULL,
    agent_run_id uuid,
    action_type varchar(32) NOT NULL,
    description text NOT NULL,
    risk_level varchar(8) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'PROPOSED',
    proposed_at timestamptz NOT NULL DEFAULT now(),
    approved_at timestamptz,
    executed_at timestamptz,
    completed_at timestamptz,
    result text,
    error_code varchar(64),
    error_message text,
    action_data jsonb NOT NULL DEFAULT '{}'::jsonb,
    CONSTRAINT pk_healing_actions PRIMARY KEY (id),
    CONSTRAINT fk_healing_actions_incident_id_incidents FOREIGN KEY (incident_id) REFERENCES incidents (id) ON DELETE RESTRICT,
    CONSTRAINT fk_healing_actions_agent_run_id_agent_runs FOREIGN KEY (agent_run_id) REFERENCES agent_runs (id) ON DELETE RESTRICT,
    CONSTRAINT ck_healing_actions_risk_level CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH')),
    CONSTRAINT ck_healing_actions_status CHECK (status IN ('PROPOSED', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED', 'EXECUTING', 'SUCCEEDED', 'FAILED'))
);
CREATE INDEX ix_healing_actions_incident_id ON healing_actions (incident_id);
CREATE INDEX ix_healing_actions_agent_run_id ON healing_actions (agent_run_id);

-- 26. approvals [Incident] 📋  Human decision gate. Generalized to deployments (ADR-011).
CREATE TABLE approvals (
    id uuid NOT NULL,
    healing_action_id uuid,
    deployment_id uuid,  -- [P]
    requested_by uuid NOT NULL,
    approved_by uuid,
    status varchar(16) NOT NULL DEFAULT 'PENDING',
    reason text,
    requested_at timestamptz NOT NULL DEFAULT now(),
    decided_at timestamptz,
    CONSTRAINT pk_approvals PRIMARY KEY (id),
    CONSTRAINT uq_approvals_healing_action_id UNIQUE (healing_action_id),
    CONSTRAINT fk_approvals_healing_action_id_healing_actions FOREIGN KEY (healing_action_id) REFERENCES healing_actions (id) ON DELETE RESTRICT,
    CONSTRAINT fk_approvals_deployment_id_deployments FOREIGN KEY (deployment_id) REFERENCES deployments (id) ON DELETE RESTRICT,
    CONSTRAINT fk_approvals_requested_by_users FOREIGN KEY (requested_by) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_approvals_approved_by_users FOREIGN KEY (approved_by) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT ck_approvals_status CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'EXPIRED'))
);
CREATE INDEX ix_approvals_healing_action_id ON approvals (healing_action_id);
CREATE INDEX ix_approvals_deployment_id ON approvals (deployment_id);
CREATE INDEX ix_approvals_requested_by ON approvals (requested_by);
CREATE INDEX ix_approvals_approved_by ON approvals (approved_by);
ALTER TABLE approvals ADD CONSTRAINT ck_approvals_one_subject CHECK (num_nonnulls(healing_action_id, deployment_id) = 1);

-- 27. audit_logs [Audit] 💡  Append-only trail of sensitive actions (README 'Audit' domain, absent in ERD).
CREATE TABLE audit_logs (
    id uuid NOT NULL,
    team_id uuid NOT NULL,
    actor_user_id uuid,
    action varchar(64) NOT NULL,
    entity_type varchar(64) NOT NULL,
    entity_id uuid,
    correlation_id varchar(64),
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_audit_logs PRIMARY KEY (id),
    CONSTRAINT fk_audit_logs_team_id_teams FOREIGN KEY (team_id) REFERENCES teams (id) ON DELETE RESTRICT,
    CONSTRAINT fk_audit_logs_actor_user_id_users FOREIGN KEY (actor_user_id) REFERENCES users (id) ON DELETE RESTRICT
);
CREATE INDEX ix_audit_logs_team_id ON audit_logs (team_id);
CREATE INDEX ix_audit_logs_actor_user_id ON audit_logs (actor_user_id);
CREATE INDEX ix_audit_logs_team_id_created_at ON audit_logs (team_id, created_at DESC);

COMMIT;

-- Circular FK note (ADR-012): when applying this in Alembic, create agent_runs in M3 with deployment_id / incident_id
-- as plain nullable UUIDs, then add fk_agent_runs_deployment_id_deployments in M5 and fk_agent_runs_incident_id_incidents in M7.
